// Helpers shared by the scripts: finding content files and matching them to schemas.

import { readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
export const DEFAULT_CONTENT_DIRECTORY = path.join(REPO_ROOT, "content");
export const SCHEMA_DIRECTORY = path.join(REPO_ROOT, "schemas");

// content/index.json is generated by `npm run index`, so it's never treated as content.
export const CONTENT_INDEX_FILE = "index.json";

// Every .json file under the content folder, as sorted paths like "facts/branches.json".
// Forward slashes on every operating system, so paths match the schema map and URLs.
export function listContentFiles(contentDirectory) {
  const found = [];
  function walk(folder) {
    for (const entry of readdirSync(folder, { withFileTypes: true })) {
      const fullPath = path.join(folder, entry.name);
      if (entry.isDirectory()) walk(fullPath);
      else if (entry.name.endsWith(".json")) {
        const relativePath = path.relative(contentDirectory, fullPath).split(path.sep).join("/");
        if (relativePath !== CONTENT_INDEX_FILE) found.push(relativePath);
      }
    }
  }
  walk(contentDirectory);
  return found.sort();
}

export function loadSchemaMap() {
  return JSON.parse(readFileSync(path.join(SCHEMA_DIRECTORY, "schema-map.json"), "utf8")).files;
}

// Turn "battles/*/units.json" into a regular expression. * matches within one folder level.
function patternToRegex(pattern) {
  const escaped = pattern.replace(/[.+?^${}()|[\]\\]/g, "\\$&").replace(/\*/g, "[^/]*");
  return new RegExp(`^${escaped}$`);
}

// Returns the schema file name for a content path, or null if no schema covers it.
export function schemaForFile(relativePath, schemaMap) {
  const entry = schemaMap.find(({ pattern }) => patternToRegex(pattern).test(relativePath));
  return entry ? entry.schema : null;
}
